-- Link each break_start to a reason (mostly Meal, some Rest)
SELECT event_id,
       CASE WHEN event_id % 6 = 0 THEN 2 ELSE 1 END,
       CASE WHEN event_id % 6 = 0 THEN 'Rest break' ELSE 'Meal break' END
FROM time_events WHERE event_type = 'break_start';

