-- Today: pending request (Sam forgot to clock out) and approved correction (Jess)
SELECT 1, event_id, 'ADD', CURRENT_DATE + TIME '15:30', 'Forgot to clock out, confirmed with supervisor', 'Admin Portal', 'Alex Morgan', CURRENT_DATE + TIME '15:35'
FROM time_events WHERE staff_id = 1 AND event_type = 'clock_in' AND event_timestamp >= CURRENT_DATE;

SELECT 2, event_id, 'EDIT', event_timestamp, CURRENT_DATE + TIME '15:00', 'Corrected clock-out time after supervisor check', 'Admin Portal', 'Alex Morgan', CURRENT_DATE + TIME '15:20', 'Marcus Webb', 'Approved', CURRENT_DATE + TIME '15:30'
FROM time_events WHERE staff_id = 2 AND event_type = 'clock_out' AND event_timestamp >= CURRENT_DATE;

-- Apply the approved EDIT amendments to the clock events
UPDATE time_events SET event_timestamp = '2026-09-08 13:51:00', is_override = TRUE, override_reason = 'Staff tapped out late after leaving; corrected from station log', override_method = 'Admin Portal'
WHERE staff_id = 13 AND event_type = 'clock_out' AND event_timestamp = '2026-09-08 14:31:00';
UPDATE time_events SET event_timestamp = '2026-09-02 14:29:00', is_override = TRUE, override_reason = 'Staff tapped out late after leaving; corrected from station log', override_method = 'Admin Portal'
WHERE staff_id = 15 AND event_type = 'clock_out' AND event_timestamp = '2026-09-02 15:09:00';
UPDATE time_events
SET event_timestamp = CURRENT_DATE + TIME '15:00', is_override = TRUE,
    override_reason = 'Corrected clock-out time after supervisor check', override_method = 'Admin Portal'
WHERE staff_id = 2 AND event_type = 'clock_out' AND event_timestamp >= CURRENT_DATE;

-- Audit trail: one row per approved amendment
SELECT 'time_events', event_id,
       CASE action WHEN 'ADD' THEN 'INSERT' WHEN 'EDIT' THEN 'UPDATE' ELSE 'DELETE' END,
       reason, approver, decided_at, adjustment_id
FROM time_adjustments WHERE status = 'Approved';

-- Audit trail: other changes with a reason (not linked to a time amendment)

-- Pay periods: fortnight A (31 Aug - 13 Sep) and fortnight B (14 - 27 Sep). Penalty hours: weekend, and the demo public holiday on 21 Sep.

-- PoC pay rule: penalty hours are paid at the overtime rate (exact award rates are a later phase)
UPDATE payroll_summary p
SET total_pay = p.ordinary_hours * s.standard_rate
              + (p.overtime_hours + p.weekend_hours + p.public_holiday_hours) * s.overtime_rate
FROM staff s
WHERE s.staff_id = p.staff_id;

